CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text, oidc_subject text UNIQUE, title text NOT NULL DEFAULT '', timezone text NOT NULL DEFAULT 'UTC', status text NOT NULL DEFAULT '', preferences jsonb NOT NULL DEFAULT '{}', disabled boolean NOT NULL DEFAULT false);
CREATE TABLE organizations(id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(org_id uuid REFERENCES organizations, user_id uuid REFERENCES users, role text NOT NULL CHECK(role IN ('owner','admin','member','guest')), active boolean NOT NULL DEFAULT true, PRIMARY KEY(org_id,user_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE teams(id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, archived boolean NOT NULL DEFAULT false, UNIQUE(org_id,id));
CREATE TABLE team_members(org_id uuid NOT NULL, team_id uuid NOT NULL, user_id uuid NOT NULL, role text NOT NULL DEFAULT 'member' CHECK(role IN ('owner','member')), PRIMARY KEY(team_id,user_id), FOREIGN KEY(org_id,team_id) REFERENCES teams(org_id,id), FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE channels(id uuid PRIMARY KEY, org_id uuid NOT NULL, team_id uuid, name text NOT NULL, description text NOT NULL DEFAULT '', kind text NOT NULL CHECK(kind IN ('standard','private','shared','direct','group')), archived boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 1, sequence bigint NOT NULL DEFAULT 0, UNIQUE(org_id,id), FOREIGN KEY(org_id,team_id) REFERENCES teams(org_id,id), FOREIGN KEY(org_id) REFERENCES organizations);
CREATE TABLE channel_members(org_id uuid NOT NULL, channel_id uuid NOT NULL, user_id uuid NOT NULL, PRIMARY KEY(channel_id,user_id), FOREIGN KEY(org_id,channel_id) REFERENCES channels(org_id,id), FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE messages(id uuid PRIMARY KEY, org_id uuid NOT NULL, channel_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users, client_id uuid NOT NULL, seq bigint NOT NULL, body text NOT NULL CHECK(length(body)<=10000), parent_id uuid, deleted boolean NOT NULL DEFAULT false, edited_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(channel_id,user_id,client_id), UNIQUE(channel_id,seq), UNIQUE(org_id,channel_id,id), FOREIGN KEY(org_id,channel_id) REFERENCES channels(org_id,id), FOREIGN KEY(org_id,channel_id,parent_id) REFERENCES messages(org_id,channel_id,id));
CREATE INDEX messages_history ON messages(channel_id,seq DESC);
CREATE INDEX messages_search ON messages USING gin(to_tsvector('english',body));
CREATE TABLE reactions(message_id uuid REFERENCES messages, user_id uuid REFERENCES users, emoji text NOT NULL, PRIMARY KEY(message_id,user_id,emoji));
CREATE TABLE read_positions(channel_id uuid REFERENCES channels, user_id uuid REFERENCES users, seq bigint NOT NULL DEFAULT 0, PRIMARY KEY(channel_id,user_id));
CREATE TABLE channel_preferences(channel_id uuid REFERENCES channels,user_id uuid REFERENCES users, pinned boolean NOT NULL DEFAULT false,muted boolean NOT NULL DEFAULT false,hidden boolean NOT NULL DEFAULT false,PRIMARY KEY(channel_id,user_id));
CREATE TABLE saved_messages(message_id uuid REFERENCES messages,user_id uuid REFERENCES users,PRIMARY KEY(message_id,user_id));
CREATE TABLE drafts(channel_id uuid REFERENCES channels,user_id uuid REFERENCES users,body text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(channel_id,user_id));
CREATE TABLE outbox(id bigserial PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations,channel_id uuid REFERENCES channels,type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_stream ON outbox(channel_id,id);
CREATE TABLE audit(id bigserial PRIMARY KEY,org_id uuid REFERENCES organizations,actor_id uuid REFERENCES users,action text NOT NULL,target text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE presence(org_id uuid NOT NULL,user_id uuid NOT NULL,state text NOT NULL DEFAULT 'available',override_until timestamptz,last_seen timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,user_id),FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE tasks(id uuid PRIMARY KEY,org_id uuid NOT NULL,channel_id uuid NOT NULL,title text NOT NULL,assignee_id uuid REFERENCES users,priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')),due_date date,status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','doing','done')),created_by uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,channel_id) REFERENCES channels(org_id,id));
CREATE TABLE task_comments(id uuid PRIMARY KEY,task_id uuid REFERENCES tasks,user_id uuid REFERENCES users,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE forms(id uuid PRIMARY KEY,org_id uuid NOT NULL,channel_id uuid NOT NULL,title text NOT NULL,questions jsonb NOT NULL,created_by uuid REFERENCES users,FOREIGN KEY(org_id,channel_id) REFERENCES channels(org_id,id));
CREATE TABLE form_responses(id uuid PRIMARY KEY,form_id uuid REFERENCES forms,user_id uuid REFERENCES users,answers jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(form_id,user_id));
CREATE TABLE meetings(id uuid PRIMARY KEY,org_id uuid REFERENCES organizations,title text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,timezone text NOT NULL,organizer_id uuid REFERENCES users,description text NOT NULL DEFAULT '',cancelled boolean NOT NULL DEFAULT false,CHECK(ends_at>starts_at));
CREATE TABLE meeting_attendees(meeting_id uuid REFERENCES meetings,user_id uuid REFERENCES users,response text NOT NULL DEFAULT 'pending' CHECK(response IN ('pending','accepted','declined','tentative')),PRIMARY KEY(meeting_id,user_id));
CREATE TABLE feedback(id uuid PRIMARY KEY,org_id uuid REFERENCES organizations,user_id uuid REFERENCES users,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE migration_jobs(id uuid PRIMARY KEY,channel_id uuid REFERENCES channels,actor_id uuid REFERENCES users,preview jsonb NOT NULL,state text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE files(id uuid PRIMARY KEY,org_id uuid NOT NULL,channel_id uuid NOT NULL,name text NOT NULL,mime text NOT NULL,bytes bigint NOT NULL,storage_key text NOT NULL,sha256 text NOT NULL,state text NOT NULL DEFAULT 'quarantined',created_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,channel_id) REFERENCES channels(org_id,id));
